    "        <div class=\"box\"><input type=\"number\" id=\"f48\" min=\"0\"></div></div>\n"
    "      <div class=\"row\"><span class=\"lbl\">Best score</span>\n"
    "        <div class=\"box\"><input type=\"number\" id=\"f44\" min=\"0\"></div></div>\n"
    "    </div>\n"
    "\n"
    "    <div class=\"side\">\n"
    "      <div class=\"plate\">\n"
    "        <div class=\"head\"><span class=\"lbl\">Name</span>\n"
    "          <span class=\"rank\"><span id=\"abbr\">PVT</span><img id=\"badge2\" alt=\"\"></span></div>\n"
    "        <div class=\"name\"><input type=\"text\" id=\"fName\" maxlength=\"8\" spellcheck=\"false\" placeholder=\"8 letters max\"><span class=\"cnt\" id=\"nameCnt\">0 / 8</span></div>\n"
    "        <div class=\"games\"><input type=\"number\" id=\"fCredits2\" min=\"0\" max=\"999\"><span>games left to play.</span></div>\n"
    "      </div>\n"
    "      <div class=\"item\"><span class=\"lbl\">Item</span>\n"
    "        <div class=\"line\"><img id=\"picGun\" alt=\"\">× <span id=\"nW\">0</span><small>weapons unlocked</small></div>\n"
    "        <div class=\"line\"><img id=\"picShirt\" alt=\"\">× <span id=\"nC\">0</span><small>costumes unlocked</small></div>\n"
    "      </div>\n"
    "    </div>\n"
    "  </div>\n"
    "\n"
    "  <div class=\"tabs\">\n"
    "    <button class=\"steel on\" data-tab=\"c\">Select costume</button>\n"
    "    <button class=\"steel\" data-tab=\"w\">Select weapon</button>\n"
    "    <button class=\"steel\" data-tab=\"k\">Config</button>\n"
    "    <span class=\"sp\"></span>\n"
    "    <span class=\"tip\">Left click wears it · right click locks or unlocks</span>\n"
    "  </div>\n"
    "  <div id=\"tab-c\"><div class=\"grid c\" id=\"gCostumes\"></div>\n"
    "    <div class=\"ghosts\"><button type=\"button\" class=\"glab\" data-open=\"xCostumes\">Not in the locker: 3 more the game can still wear &#9656;</button><div class=\"xlist\" id=\"xCostumes\" hidden></div></div>\n"
    "    <div class=\"tools\"><span class=\"count\" id=\"cc\"></span><button class=\"steel small\" data-all=\"c\">Unlock all</button><button class=\"steel small\" data-none=\"c\">Lock all</button></div></div>\n"
    "  <div id=\"tab-w\" hidden><div class=\"grid w\" id=\"gWeapons\"></div>\n"
    "    <div class=\"ghosts\"><button type=\"button\" class=\"glab\" data-open=\"xWeapons\">Not in the locker: 11 more the game can still wear &#9656;</button><div class=\"xlist\" id=\"xWeapons\" hidden></div></div>\n"
    "    <div class=\"tools\"><span class=\"count\" id=\"cw\"></span><button class=\"steel small\" data-all=\"w\">Unlock all</button><button class=\"steel small\" data-none=\"w\">Lock all</button></div></div>\n"
    "  <div id=\"tab-k\" hidden>\n"
    "    <div class=\"config\">\n"
    "      <button class=\"steel\" id=\"tSub\">Sub title<b id=\"subState\">ON</b></button>\n"
    "      <button class=\"steel\" id=\"tApp\">Change appearance<b id=\"appState\">NORMAL</b></button>\n"
    "      <button class=\"steel\" id=\"tNew\">Mark my changes as NEW<b id=\"newState\">YES</b></button>\n"
    "    </div>\n"
    "    <p class=\"cfgnote\">The game's CONFIG menu has exactly these two settings: subtitles on or off, and the in-game display in NORMAL or SIMPLE mode. Changing one here also makes the CONFIG button available on that card.\n"
    "      The third button decides what the game shows the next time the card goes in: with YES, the costumes and\n"
    "      weapons you just changed are announced with a NEW flag on the PLAYER'S DATA screen, exactly as if you had\n"
    "      won them in a game; with NO, the card looks like nothing changed.</p>\n"
    "  </div>\n"
    "\n"
    "  <details><summary>Other data stored on the card</summary><table id=\"raw\"></table></details>\n"
    "</div>\n"
    "\n"
    "\n"
    "</div>\n"
    "\n"
    "<script>\n"
    "// Ghost Squad card tables: item bits and names, where each picture sits in the game's\n"
    "// sprite archive, EXP milestones, class thresholds. Facts about the format, not artwork.\n"
    "// Copyright (c) 2026 Reda Cherif-Touil\n"
    "// SPDX-License-Identifier: GPL-3.0-or-later\n"
    "window.GSCARD_ITEMS = {\"costumes\": [{\"bit\": 0, \"name\": \"GHOST SQUAD\", \"tex\": 0, \"tex_en\": 0, \"tex_locked\": 1}, {\"bit\": 4, \"name\": \"JUNGLE\", \"tex\": 2, \"tex_en\": 2, \"tex_locked\": 3}, {\"bit\": 3, \"name\": \"DESERT\", \"tex\": 4, \"tex_en\": 4, \"tex_locked\": 5}, {\"bit\": 5, \"name\": \"TOUGH GUY\", \"tex\": 8, \"tex_en\": 8, \"tex_locked\": 9}, {\"bit\": 6, \"name\": \"POLICE MAN\", \"tex\": 6, \"tex_en\": 6, \"tex_locked\": 7}, {\"bit\": 7, \"name\": \"WW2\", \"tex\": 12, \"tex_en\": 12, \"tex_locked\": 13}, {\"bit\": 8, \"name\": \"URBAN\", \"tex\": 16, \"tex_en\": 16, \"tex_locked\": 17}, {\"bit\": 9, \"name\": \"COWBOY\", \"tex\": 14, \"tex_en\": 14, \"tex_locked\": 15}, {\"bit\": 10, \"name\": \"VIRTUA COP\", \"tex\": 18, \"tex_en\": 18, \"tex_locked\": 19}, {\"bit\": 11, \"name\": \"SKY\", \"tex\": 10, \"tex_en\": 10, \"tex_locked\": 11}, {\"bit\": 12, \"name\": \"NINJA\", \"tex\": 22, \"tex_en\": 22, \"tex_locked\": 23}, {\"bit\": 13, \"name\": \"PANDA\", \"tex\": 24, \"tex_en\": 24, \"tex_locked\": 25}, {\"bit\": 14, \"name\": \"FUTURE WARRIOR\", \"tex\": 20, \"tex_en\": 20, \"tex_locked\": 21}, {\"bit\": 15, \"name\": \"GOLD\", \"tex\": 26, \"tex_en\": 26, \"tex_locked\": 27}], \"weapons\": [{\"bit\": 1, \"name\": \"XM-2119\", \"tex\": 56, \"tex_en\": 56, \"tex_locked\": 57}, {\"bit\": 2, \"name\": \"M94R\", \"tex\": 58, \"tex_en\": 58, \"tex_locked\": 59}, {\"bit\": 3, \"name\": \"MP10\", \"tex\": 60, \"tex_en\": 60, \"tex_locked\": 61}, {\"bit\": 6, \"name\": \"AR4A\", \"tex\": 62, \"tex_en\": 62, \"tex_locked\": 63}, {\"bit\": 4, \"name\": \"TK1B\", \"tex\": 64, \"tex_en\": 65, \"tex_locked\": 66}, {\"bit\": 7, \"name\": \"TR14\", \"tex\": 67, \"tex_en\": 68, \"tex_locked\": 69}, {\"bit\": 8, \"name\": \"G50\", \"tex\": 70, \"tex_en\": 70, \"tex_locked\": 71}, {\"bit\": 5, \"name\": \"CPG7\", \"tex\": 72, \"tex_en\": 73, \"tex_locked\": 74}, {\"bit\": 9, \"name\": \"SAW24\", \"tex\": 75, \"tex_en\": 76, \"tex_locked\": 77}, {\"bit\": 10, \"name\": \"XMW21\", \"tex\": 78, \"tex_en\": 79, \"tex_locked\": 80}, {\"bit\": 11, \"name\": \"M209\", \"tex\": 81, \"tex_en\": 81, \"tex_locked\": 82}, {\"bit\": 12, \"name\": \"TM9V\", \"tex\": 83, \"tex_en\": 84, \"tex_locked\": 85}, {\"bit\": 13, \"name\": \"PM6\", \"tex\": 86, \"tex_en\": 87, \"tex_locked\": 88}, {\"bit\": 14, \"name\": \"P4512\", \"tex\": 89, \"tex_en\": 89, \"tex_locked\": 90}, {\"bit\": 15, \"name\": \"P44M\", \"tex\": 91, \"tex_en\": 92, \"tex_locked\": 93}, {\"bit\": 16, \"name\": \"M45R\", \"tex\": 94, \"tex_en\": 94, \"tex_locked\": 95}, {\"bit\": 17, \"name\": \"GUARDIAN II\", \"tex\": 96, \"tex_en\": 96, \"tex_locked\": 97}, {\"bit\": 18, \"name\": \"GUARDIAN I\", \"tex\": 98, \"tex_en\": 99, \"tex_locked\": 100}, {\"bit\": 23, \"name\": \"M4E\", \"tex\": 101, \"tex_en\": 101, \"tex_locked\": 102}, {\"bit\": 24, \"name\": \"SG112\", \"tex\": 103, \"tex_en\": 103, \"tex_locked\": 104}, {\"bit\": 25, \"name\": \"ABG1\", \"tex\": 105, \"tex_en\": 106, \"tex_locked\": 107}, {\"bit\": 19, \"name\": \"CAC82\", \"tex\": 108, \"tex_en\": 109, \"tex_locked\": 110}, {\"bit\": 20, \"name\": \"SPR3\", \"tex\": 111, \"tex_en\": 112, \"tex_locked\": 113}, {\"bit\": 21, \"name\": \"SR308\", \"tex\": 114, \"tex_en\": 115, \"tex_locked\": 116}, {\"bit\": 22, \"name\": \"SPR11\", \"tex\": 117, \"tex_en\": 118, \"tex_locked\": 119}]};\n"
    "window.GSCARD_PROG = {\"milestones\": [0, 190, 717, 1552, 2605, 3828, 5190, 6669, 8249, 9919, 11669, 13491, 15380, 17329, 19335, 21393, 23500, 25653, 27850, 30088, 32365, 34679, 37028, 39411, 41826, 44273, 46749, 49254, 51787, 54346, 56931, 59541, 62175, 64833, 67513, 70215, 72939, 75683, 78448, 81232, 84035, 86857, 89698, 92556, 95432, 98325, 101235, 104161, 107103, 110061, 113034, 116022, 119025, 122042, 125074, 128120, 131179, 134252, 137338, 140437, 143549, 146673, 149810, 152959, 156120, 159293, 162477, 165672, 168879, 172097, 175326, 178566, 181816, 185077, 188348, 191629, 194920, 198221, 201532, 204853, 208183, 211523, 214872, 218230, 221597, 224973, 228358, 231752, 235155, 238566, 241986, 245414, 248851, 252296, 255749, 259210, 262679, 266156, 269641, 273141], \"class_thresholds\": [4, 7, 10, 13, 15, 18, 20, 23, 27, 30, 34, 38, 43, 50, 60, 99]};\n"
    "window.GSCARD_HIDDEN = {\"weapons\": [{\"idx\": 26, \"name\": \"SAN92\", \"note\": \"missile launcher\"}, {\"idx\": 27, \"name\": \"CAC80\", \"note\": \"sniper rifle\"}, {\"idx\": 28, \"name\": \"CAC80 II\", \"note\": \"second sniper rifle, same name plate\"}, {\"idx\": 29, \"name\": \"SAW25\", \"note\": \"heavy machinegun, brother of the SAW24\"}, {\"idx\": 30, \"name\": \"GRENADE\", \"note\": \"no name plate in the HUD\"}, {\"idx\": 31, \"name\": \"GGL50\", \"note\": \"grenade launcher\"}, {\"idx\": 32, \"name\": \"SMOKE GRENADE\"}, {\"idx\": 33, \"name\": \"CS GRENADE\"}, {\"idx\": 34, \"name\": \"FLASH GRENADE\"}, {\"idx\": 35, \"name\": \"ROAR GRENADE\"}, {\"idx\": 36, \"name\": \"STINGBALL GRENADE\", \"note\": \"three at a time\"}], \"costumes\": [{\"idx\": 1, \"name\": \"BETA\", \"model\": \"BETA1P/BETA2P\", \"note\": \"squad ally, white band on the helmet\"}, {\"idx\": 2, \"name\": \"GAMMA\", \"model\": \"GAMMA1P/GAMMA2P\", \"note\": \"squad ally, red band on the helmet\"}, {\"idx\": 16, \"name\": \"FORCE X\", \"model\": \"FORCE1X/FORCE2X\", \"note\": \"seen as a terrorist, at a distance only\"}]};\n"
    "window.GSCARD_ATLAS = {\"badges\": [165, 164, 163, 162, 161, 160, 159, 58, 57, 56, 55, 54, 53, 52, 51, 50, 49], \"icons\": {\"sprite\": 338, \"gun\": [48, 37, 78, 67], \"shirt\": [48, 77, 78, 107]}};\n"
    "\n"
    "</script>\n"
    "<script>\n"
    "\"use strict\";\n"
    "const SBHU = 0x40, MIRROR = 0x140, OFF_COST = 0x78, OFF_WEAP = 0x74;\n"
    "// what the game itself puts on a brand new card: two costumes, one weapon,\n"
    "// and the 56 progress markers it lays down (groups of 17, 19 and 20 items)\n"
    "const VIRGIN_WEAP = 0x02, VIRGIN_COST = 0x11;\n"
    "const VIRGIN_MARKS = \"11101100111110011\" + \"0101110000010001111\" + \"11111010111111000011\";\n"
    "let ART = {}, UI = {}, ARTSRC = null;                    // filled in only by an import\n"
    "const PROG = window.GSCARD_PROG || {milestones:[0], class_thresholds:[]};\n"
    "const ITEMS = window.GSCARD_ITEMS || {costumes:[], weapons:[]};\n"
    "const MS = PROG.milestones, CT = PROG.class_thresholds, MAXEXP = MS[98];\n"
    "const RANKS = [\"Private\",\"Private First Class\",\"Sergeant\",\"Master Sergeant\",\"Warrant Officer\",\"Chief Warrant Officer\",\n"
    "  \"Second Lieutenant\",\"First Lieutenant\",\"Captain\",\"Major\",\"Lieutenant Colonel\",\"Colonel\",\"Brigadier General\",\n"
    "  \"Major General\",\"Lieutenant General\",\"General\",\"Marshal\"];\n"
    "const ABBR = [\"PVT\",\"PFC\",\"SGT\",\"MSG\",\"WO\",\"CW\",\"2LT\",\"1LT\",\"CPT\",\"MAJ\",\"LTC\",\"COL\",\"BG\",\"MG\",\"LTG\",\"GEN\",\"MAR\"];\n"
    "const $ = id => document.getElementById(id);\n"
    "const sb = o => SBHU + o;\n"
    "const hex = v => \"0x\" + v.toString(16).padStart(8, \"0\");\n"
    "const stamp = t => t ? new Date(t * 1000).toLocaleString() : \"—\";\n"
    "const levelOf = exp => { let n = 0; for (let i = 1; i <= 98; i++) if (MS[i] <= exp) n++; return n; };   // stored level 0..98\n"
    "const classOf = lvl => Math.min(16, CT.filter(t => t <= lvl + 1).length);\n"
    "\n"
    "let card = null, fileName = \"card.bin\";\n"
    "let openMasks = null, flagNew = true, expEdited = false;   // openMasks = the two masks as the file was opened\n"
    "function crc32jam(b, from, len){ let c = 0xFFFFFFFF;\n"
    "  for (let i = from; i < from + len; i++){ c ^= b[i]; for (let k = 0; k < 8; k++) c = (c >>> 1) ^ (0xEDB88320 & -(c & 1)); }\n"
    "  return c >>> 0; }\n"
    "const rd32 = o => (card[o] | card[o+1]<<8 | card[o+2]<<16 | card[o+3]<<24) >>> 0;\n"
    "const wr32 = (o,v) => { card[o]=v&255; card[o+1]=v>>>8&255; card[o+2]=v>>>16&255; card[o+3]=v>>>24&255; };\n"
    "function seal(){ wr32(sb(0xFC), crc32jam(card, SBHU, 0xFC)); card.copyWithin(MIRROR, SBHU, SBHU + 0x100); }\n"
    "function say(m, k){ const s = $(\"status\"); s.hidden = false; s.className = k || \"\";\n"
    "  s.innerHTML = (k === \"ok\" ? '<span class=\"ic\">✓</span>' : k === \"err\" ? '<span class=\"ic\">✕</span>' : \"\") + \"<span></span>\"; s.lastChild.textContent = m; }\n"
    "function paintArt(){\n"
    "  for (const el of [$(\"gWeapons\"), $(\"gCostumes\")])\n"
    "    for (const s of el.children){\n"
    "      const src = ART[s.dataset.key + s.dataset.bit] || \"\";\n"
    "      s.querySelector(\"img\").src = src; s.classList.toggle(\"art\", !!src);\n"
    "      s.classList.toggle(\"haslock\", !!ART[s.dataset.key + s.dataset.bit + \"L\"]);\n"
    "    }\n"
    "  for (const el of [$(\"xWeapons\"), $(\"xCostumes\")])\n"
    "    for (const s of el.children){\n"
    "      const n = ART[\"h\" + s.dataset.idx + \"n\"], i = ART[\"h\" + s.dataset.idx + \"i\"];\n"
    "      if (n) s.querySelector(\".xn\").src = n;\n"
    "      if (i) s.querySelector(\".xi\").src = i;\n"
    "      s.classList.toggle(\"plated\", !!n);                  // no plate: the name stays in text\n"
    "    }\n"
    "  for (const [id, v] of [[\"picGun\", UI.gun], [\"picShirt\", UI.shirt]]){ $(id).src = v || \"\"; $(id).hidden = !v; }\n"
    "}\n"
    "/* ---- the pictures come from the program, not from the page --------------------\n"
    "   The C++ side finds the sprite archive inside the player's own copy of the game,\n"
    "   decodes it and writes the pictures next to the program; they are then served\n"
    "   from here like any other file. The naming is fixed, so the page can build every\n"
    "   address itself. */\n"
    "const ATLAS = window.GSCARD_ATLAS || { badges: [], icons: {} };\n"
    "/* Items with a model in the game but no locker bit and no picture: costume\n"
    "   indices the setter accepts (0-16) beyond the 14 the locker lists, and weapon\n"
    "   indices up to 36 beyond the 25 it lists. They can only be worn. */\n"
    "const HIDDEN = window.GSCARD_HIDDEN || {weapons:[], costumes:[]};\n"
    "const hiddenW = i => HIDDEN.weapons.find(h => h.idx === i);\n"
    "const hiddenC = i => HIDDEN.costumes.find(h => h.idx === i);\n"
    "let artLang = null;\n"
    "\n"
    "const slug = n => n.toLowerCase().replace(/ /g, \"-\");\n"
    "const two = n => String(n).padStart(2, \"0\");\n"
    "\n"
    "async function useArt(lang){\n"
    "  if (!lang){ ART = {}; UI = {}; artLang = null; paintArt(); if (card) refresh(); return; }\n"
    "  const want = [];\n"
    "  for (const [list, key, dir] of [[ITEMS.costumes, \"c\", \"costumes\"], [ITEMS.weapons, \"w\", \"weapons\"]])\n"
    "    for (const it of list){\n"
    "      const stem = `${dir}/${two(it.bit)}-${slug(it.name)}`;\n"
    "      want.push([key + it.bit, stem + \".png\"]);\n"
    "      want.push([key + it.bit + \"L\", stem + \"-locked.png\"]);\n"
    "    }\n"
    "  for (let i = 0; i < 17; i++) want.push([\"badge\" + i, `badges/${two(i)}.png`]);\n"
    "  for (const it of HIDDEN.weapons){                       // the HUD's own name plates\n"
    "    want.push([\"h\" + it.idx + \"n\", `hidden/${two(it.idx)}-name.png`]);\n"
    "    want.push([\"h\" + it.idx + \"i\", `hidden/${two(it.idx)}-icon.png`]);\n"
    "  }\n"
    "  want.push([\"gun\", \"icons/gun.png\"]); want.push([\"shirt\", \"icons/shirt.png\"]);\n"
    "  want.push([\"plate\", \"buttons/plate.png\"]);\n"
    "\n"
    "  const art = {}, ui = {};\n"
    "  let done = 0;\n"
    "  for (const [key, file] of want){\n"
    "    const r = await hostImage(lang, file);\n"
    "    if (r && r.ok){\n"
    "      const url = \"data:image/png;base64,\" + r.data;\n"
    "      if (key === \"plate\"){\n"
    "        document.documentElement.style.setProperty(\"--plate\", `url(${url})`);\n"
    "        document.documentElement.classList.add(\"hasplate\");\n"
    "      }\n"
    "      else if (key.startsWith(\"badge\") || key === \"gun\" || key === \"shirt\") ui[key] = url;\n"
    "      else art[key] = url;\n"
    "    }\n"
    "    if (++done % 24 === 0) say(`Loading pictures... ${Math.round(done * 100 / want.length)}%`);\n"
    "  }\n"
    "  ART = art; UI = ui; artLang = lang;\n"
    "  paintArt(); if (card) refresh();\n"
    "}\n"
    "\n"
    "async function openGame(){\n"
    "  say(\"Choose your copy of Ghost Squad...\");\n"
    "  const r = await hostPickGame();\n"
    "  if (!r.ok) return say(r.err || \"No artwork in that file.\", \"err\");\n"
    "  say(`Artwork found in ${r.name} - now pick the edition you want.`, \"ok\");\n"
    "  $(\"langAsk\").textContent = \"Which edition of the artwork?\";\n"
    "  $(\"langPick\").hidden = false;\n"
    "}\n"
    "\n"
    "async function buildArt(lang){\n"
    "  say(\"Writing the pictures...\");\n"
    "  const r = await hostImport(lang);\n"
    "  if (!r.ok) return say(r.err || \"Could not write the pictures.\", \"err\");\n"
    "  await useArt(lang);\n"
    "  say(`Artwork imported - ${lang === \"japanese\" ? \"Japanese\" : \"World\"} edition, kept in assets/${lang}.`, \"ok\");\n"
    "}\n"
    "\n"
    "function blankCard(){\n"
    "  const c = new Uint8Array(2048);\n"
    "  c.set([0x95,0x71,0x36,0x40], 0x20); c.set([0x00,0x00,0x03,0xF2], 0x34);\n"
    "  const w = (o,v)=>{c[o]=v&255;c[o+1]=v>>>8&255;c[o+2]=v>>>16&255;c[o+3]=v>>>24&255;};\n"
    "  w(SBHU+0x00,0x55484253); w(SBHU+0x04,0x3F2); w(SBHU+0x08,0x4754584E); w(SBHU+0x0C,0x100);\n"
    "  const now = Math.floor(Date.now()/1000); w(SBHU+0x10,now); w(SBHU+0x14,now);\n"
    "  w(SBHU+0x24,100); w(SBHU+OFF_WEAP,VIRGIN_WEAP); w(SBHU+OFF_COST,VIRGIN_COST);\n"
    "  for (let i = 0; i < VIRGIN_MARKS.length; i++) c[SBHU+0x80+i] = +VIRGIN_MARKS[i];\n"
    "  c[SBHU+0x7C]=1; c[SBHU+0x6D]=0xFF;\n"
    "  const keep = card; card = c; seal(); card = keep; return c;\n"
    "}\n"
    "function load(bytes, name){\n"
    "  if (bytes.length !== 2048) return say(`This file is ${bytes.length} bytes; a card is 2048.`, \"err\");\n"
    "  card = bytes; fileName = name;\n"
    "  const magic = String.fromCharCode(...card.slice(sb(0), sb(4))), game = String.fromCharCode(...card.slice(sb(8), sb(12)));\n"
    "  if (magic !== \"SBHU\") return say(`No save block found (signature \"${magic}\"). Not a Ghost Squad card.`, \"err\");\n"
    "  if (game !== \"NXTG\")  return say(`This card belongs to another game (\"${game}\").`, \"err\");\n"
    "  const ok0 = rd32(sb(0xFC)) === crc32jam(card, SBHU, 0xFC), ok1 = rd32(MIRROR+0xFC) === crc32jam(card, MIRROR, 0xFC);\n"
    "  openMasks = { w: rd32(sb(OFF_WEAP)), c: rd32(sb(OFF_COST)), f: rd32(sb(0xB8)) };\n"
    "  expEdited = false;\n"
    "  const odd = card[sb(0x5C)] !== levelOf(rd32(sb(0x50))) || card[sb(0x64)] !== classOf(card[sb(0x5C)]);\n"
    "  const extra = odd ? \" The level or class on this card does not follow its EXP; move the EXP slider to line them up.\" : \"\";\n"
    "  say(ok0 && ok1 ? `${name} loaded — card data intact.${extra}` : `${name} loaded — the card data was damaged; saving will repair it.${extra}`, ok0 && ok1 ? \"ok\" : \"err\");\n"
    "  $(\"drop\").hidden = true; $(\"editor\").hidden = false; $(\"btnSave\").disabled = false;\n"
    "  build(); refresh();\n"
    "}\n"
    "function build(){\n"
    "  if ($(\"gWeapons\").children.length) return;\n"
    "  for (const [el, list, key] of [[$(\"gWeapons\"), ITEMS.weapons, \"w\"], [$(\"gCostumes\"), ITEMS.costumes, \"c\"]]){\n"
    "    for (const it of list){\n"
    "      const d = document.createElement(\"div\"); d.className = \"slot\"; d.dataset.bit = it.bit; d.title = it.name;\n"
    "      d.dataset.key = key; d.innerHTML = `<img alt=\"${it.name}\"><b class=\"nm\">${it.name}</b>`;\n"
    "      const off = sb(key === \"w\" ? OFF_WEAP : OFF_COST);\n"
    "      d.onclick = () => {                                   // left click wears it\n"
    "        wr32(off, rd32(off) | (1 << it.bit));               // the game never wears a locked item\n"
    "        card[sb(key === \"w\" ? 0x7C : 0x7D)] = it.bit; if (key === \"c\") card[sb(0x7E)] = it.bit; refresh(); };\n"
    "      d.oncontextmenu = e => { e.preventDefault();          // right click locks or unlocks\n"
    "        wr32(off, rd32(off) ^ (1 << it.bit)); fixWorn(); refresh(); };\n"
    "      el.appendChild(d);\n"
    "    }\n"
    "  }\n"
    "  for (const [el, list, key, at] of [[$(\"xWeapons\"), HIDDEN.weapons, \"w\", 0x7C], [$(\"xCostumes\"), HIDDEN.costumes, \"c\", 0x7D]]){\n"
    "    for (const it of list){\n"
    "      const d = document.createElement(\"div\"); d.className = \"slot x\"; d.dataset.idx = it.idx; d.dataset.key = key;\n"
    "      d.title = `${it.name} - index ${it.idx}${it.model ? \", model \" + it.model : \"\"}${it.note ? \" - \" + it.note : \"\"}`;\n"
    "      d.innerHTML = `<img class=\"xi\" alt=\"\"><img class=\"xn\" alt=\"${it.name}\"><b class=\"nm\">${it.name}</b><i class=\"xd\">${it.idx}</i>`;\n"
    "      d.onclick = () => { card[sb(at)] = it.idx; if (key === \"c\") card[sb(0x7E)] = it.idx; refresh(); };\n"
    "      el.appendChild(d);\n"
    "    }\n"
    "  }\n"
    "  window.MORE = [[\"Card insertions\",\"in28\"],[\"Card number\",()=>hex(rd32(sb(0x20)))],\n"
    "    [\"Last written\",()=>stamp(rd32(sb(0x14)))],\n"
    "    [\"State\",()=>{const f=rd32(sb(0x2C));return (f&1?\"registered\":\"blank\")+(f&2?\", used up\":\"\");}],\n"
    "    [\"Total score (kept, never shown by the game)\",()=>rd32(sb(0xC4))]];\n"
    "  $(\"raw\").innerHTML = window.MORE.map(([l,f],i)=>`<tr><td>${l}</td><td>${f===\"in28\"?'<input type=\"number\" id=\"f28\" min=\"0\">':`<span id=\"more${i}\"></span>`}</td></tr>`).join(\"\");\n"
    "  paintArt();\n"
    "}\n"
    "function lockArt(s, on){                      // the game has its own picture for a locked item\n"
    "  const k = s.dataset.key + s.dataset.bit, src = (on ? ART[k] : ART[k + \"L\"] || ART[k]) || \"\";\n"
    "  const img = s.querySelector(\"img\"); if (img && img.getAttribute(\"src\") !== src) img.src = src;\n"
    "}\n"
    "function fixWorn(){                     // the game never wears something that is locked\n"
    "  for (const [off, list, at] of [[OFF_COST, ITEMS.costumes, 0x7D], [OFF_WEAP, ITEMS.weapons, 0x7C]]){\n"
    "    const m = rd32(sb(off)), worn = card[sb(at)];\n"
    "    if (!(m >>> worn & 1) && !(at === 0x7C ? hiddenW(worn) : hiddenC(worn))){\n"
    "      const first = (list.find(i => m >>> i.bit & 1) || list[0]).bit;\n"
    "      card[sb(at)] = first; if (at === 0x7D) card[sb(0x7E)] = first;\n"
    "    }\n"
    "  }\n"
    "}\n"
    "function refresh(){\n"
    "  const cm = rd32(sb(OFF_COST)), wm = rd32(sb(OFF_WEAP));\n"
    "  const firstOf = (m, list) => { for (const it of list) if (m >>> it.bit & 1) return it.bit; return list[0].bit; };\n"
    "  if (!(cm >>> card[sb(0x7D)] & 1) && !hiddenC(card[sb(0x7D)])){ const b = firstOf(cm, ITEMS.costumes); card[sb(0x7D)] = b; card[sb(0x7E)] = b; }\n"
    "  if (!(wm >>> card[sb(0x7C)] & 1) && !hiddenW(card[sb(0x7C)])) card[sb(0x7C)] = firstOf(wm, ITEMS.weapons);   // the game never wears a locked item\n"
    "  let nc = 0, nw = 0;\n"
    "  for (const s of $(\"gCostumes\").children){ const on = cm >>> +s.dataset.bit & 1; s.classList.toggle(\"off\", !on); s.classList.toggle(\"eq\", +s.dataset.bit === card[sb(0x7D)]); lockArt(s, on); nc += on; }\n"
    "  for (const s of $(\"gWeapons\").children){ const on = wm >>> +s.dataset.bit & 1; s.classList.toggle(\"off\", !on); s.classList.toggle(\"eq\", +s.dataset.bit === card[sb(0x7C)]); lockArt(s, on); nw += on; }\n"
    "  $(\"cc\").textContent = `${nc} of ${ITEMS.costumes.length} costumes unlocked`; $(\"cw\").textContent = `${nw} of ${ITEMS.weapons.length} weapons unlocked`;\n"
    "  $(\"nW\").textContent = nw; $(\"nC\").textContent = nc;\n"
    "  for (const [el, at] of [[$(\"xCostumes\"), 0x7D], [$(\"xWeapons\"), 0x7C]]){\n"
    "    let worn = false;\n"
    "    for (const s of el.children){ const on = +s.dataset.idx === card[sb(at)]; s.classList.toggle(\"eq\", on); worn = worn || on; }\n"
    "    if (worn && el.hidden){ const b = document.querySelector(`[data-open=\"${el.id}\"]`);\n"
    "      if (b) b.onclick(); else el.hidden = false; }      /* something unlisted is worn: show it */\n"
    "  }\n"
    "  const eqc = hiddenC(card[sb(0x7D)]) || ITEMS.costumes.find(c => c.bit === card[sb(0x7D)]) || ITEMS.costumes[0];\n"
    "  const eqw = hiddenW(card[sb(0x7C)]) || ITEMS.weapons.find(w => w.bit === card[sb(0x7C)]);\n"
    "  const psrc = eqc.idx !== undefined ? \"\" : (UI[\"bust\" + eqc.bit] || ART[\"c\" + eqc.bit] || \"\");\n"
    "  $(\"portrait\").src = psrc; $(\"well\").classList.toggle(\"art\", !!psrc);\n"
    "  $(\"portName\").innerHTML = `${eqc.name}<br><small style=\"opacity:.75\">${eqw ? eqw.name : \"?\"}</small>`;\n"
    "  $(\"who\").textContent = `${eqc.name} · ${eqw ? eqw.name : \"?\"}`;   // the column is narrow now\n"
    "\n"
    "  const exp = rd32(sb(0x50));\n"
    "  let lvl = expEdited ? levelOf(exp) : card[sb(0x5C)], cls = expEdited ? classOf(lvl) : card[sb(0x64)];\n"
    "  lvl = Math.max(0, Math.min(98, lvl)); cls = Math.max(0, Math.min(16, cls));\n"
    "  if (expEdited){ card[sb(0x5C)] = lvl; card[sb(0x64)] = cls; }   // only when the player actually moved it\n"
    "  $(\"f50\").textContent = exp.toLocaleString(\"en-US\");\n"
    "  if ($(\"fLevel\") !== document.activeElement) $(\"fLevel\").value = lvl + 1;\n"
    "  const lo = MS[lvl], hi = MS[lvl + 1];                 // this level starts at lo; the next one at hi\n"
    "  const sl = $(\"expSlide\"); sl.min = lo; sl.max = Math.max(lo, hi - 1); sl.value = exp;   // never lands on the next milestone\n"
    "  const frac = Math.max(0, Math.min(1, (exp - lo) / Math.max(1, hi - lo)));\n"
    "  $(\"expfill\").style.width = (100 * frac) + \"%\";\n"
    "  const txt = lvl >= 98 ? \"MAX LEVEL\" : `${hi - exp} EXP TO LEVEL UP`;\n"
    "  $(\"expTxt\").textContent = txt; $(\"expTxt2\").textContent = txt;\n"
    "  $(\"expTxt2\").style.clipPath = `inset(0 ${100 - 100 * frac}% 0 0)`;\n"
    "  const rn = $(\"rankName\"), rname = RANKS[cls];          // long ranks must stay on one line\n"
    "  rn.textContent = rname;\n"
    "  rn.style.fontSize = rname.length > 19 ? \"12.5px\" : rname.length > 16 ? \"14px\" : rname.length > 12 ? \"16px\" : \"19px\";\n"
    "   $(\"abbr\").textContent = ABBR[cls];\n"
    "  for (const id of [\"rankBadge\",\"badge2\"]){ $(id).src = UI[\"badge\" + cls] || \"\"; $(id).hidden = !UI[\"badge\" + cls]; }\n"
    "\n"
    "  for (const [id, off] of [[\"f48\",0x48],[\"f44\",0x44],[\"fCredits2\",0x24],[\"f28\",0x28]]){\n"
    "    const el = $(id); if (el && el !== document.activeElement) el.value = rd32(sb(off)); }\n"
    "  const name = String.fromCharCode(...card.slice(sb(0x30), sb(0x38))).replace(/\\0+$/, \"\");\n"
    "  if ($(\"fName\") !== document.activeElement) $(\"fName\").value = name;\n"
    "  $(\"nameCnt\").textContent = `${name.length} / 8`;\n"
    "  const cfg = rd32(sb(0xCC));\n"
    "  $(\"subState\").textContent = (cfg & 4) ? \"OFF\" : \"ON\"; $(\"appState\").textContent = (cfg & 2) ? \"SIMPLE\" : \"NORMAL\";\n"
    "  (window.MORE || []).forEach(([, f], i) => { const c = $(\"more\" + i); if (c) c.textContent = f(); });\n"
    "  if (window.maybeZoom) requestAnimationFrame(maybeZoom);   // only if the page really changed height\n"
    "}\n"
    "document.addEventListener(\"input\", e => {\n"
    "  const id = e.target.id; let v = parseInt(e.target.value, 10); if (isNaN(v)) v = 0; v = Math.max(0, v);\n"
    "  if (id === \"expSlide\"){ expEdited = true; wr32(sb(0x50), v); refresh(); }\n"
    "  else if (id === \"fLevel\"){ const L = Math.max(1, Math.min(99, v)); if (String(L) !== e.target.value) e.target.value = L;\n"
    "    expEdited = true; wr32(sb(0x50), MS[L - 1]); refresh(); }                                   // typing a level puts EXP at that level's start\n"
    "  else if (id === \"f48\"){ wr32(sb(0x48), v); refresh(); }\n"
    "  else if (id === \"f44\"){ wr32(sb(0x44), v); refresh(); }\n"
    "  else if (id === \"f28\"){ wr32(sb(0x28), v); refresh(); }\n"
    "  else if (id === \"fCredits2\"){ const C = Math.min(999, v); if (String(C) !== e.target.value) e.target.value = C; wr32(sb(0x24), C); refresh(); }\n"
    "  else if (id === \"fName\"){ const s = e.target.value.toUpperCase().replace(/[^\\x20-\\x7E]/g, \"\").slice(0, 8);\n"
    "    if (s !== e.target.value) e.target.value = s; for (let i = 0; i < 8; i++) card[sb(0x30)+i] = i < s.length ? s.charCodeAt(i) : 0;\n"
    "    $(\"nameCnt\").textContent = `${s.length} / 8`; }\n"
    "});\n"
    "for (const b of document.querySelectorAll(\"[data-tab]\")) b.onclick = () => {\n"
    "  for (const x of document.querySelectorAll(\"[data-tab]\")) x.classList.toggle(\"on\", x === b);\n"
    "  for (const t of \"cwk\") $(\"tab-\" + t).hidden = b.dataset.tab !== t;\n"
    "  applyZoom(); };                                        /* the weapons tab is one row taller */\n"
    "for (const b of document.querySelectorAll(\"[data-all],[data-none]\")) b.onclick = () => {\n"
    "  const w = (b.dataset.all || b.dataset.none) === \"w\", list = w ? ITEMS.weapons : ITEMS.costumes, off = sb(w ? OFF_WEAP : OFF_COST);\n"
    "  let m = 0; if (b.dataset.all) for (const it of list) m |= 1 << it.bit; else m = 1 << list[0].bit;   // keep the starting item\n"
    "  wr32(off, m >>> 0); refresh(); };\n"
    "$(\"tSub\").onclick = () => { wr32(sb(0xCC), rd32(sb(0xCC)) ^ 4); wr32(sb(0xB8), rd32(sb(0xB8)) | 0x400); refresh(); };\n"
    "$(\"tApp\").onclick = () => { wr32(sb(0xCC), rd32(sb(0xCC)) ^ 2); wr32(sb(0xB8), rd32(sb(0xB8)) | 0x200); refresh(); };\n"
    "for (const b of document.querySelectorAll(\"[data-open]\")) b.onclick = () => {\n"
    "  const g = $(b.dataset.open); g.hidden = !g.hidden;\n"
    "  b.innerHTML = b.innerHTML.replace(g.hidden ? \"\\u25be\" : \"\\u25b8\", g.hidden ? \"\\u25b8\" : \"\\u25be\");\n"
    "  applyZoom(); };                                        /* the window follows the fold */\n"
    "$(\"tNew\").onclick = () => { flagNew = !flagNew; $(\"newState\").textContent = flagNew ? \"YES\" : \"NO\"; };\n"
    "let sizing = false, again = false, winScale = null, picked = false, desk = {w:0, h:0};\n"
    "let unit = 1;                  // window units per page pixel, measured on the first pass\n"
    "let lastW = -1, lastH2 = -1;   // the size the window was last asked for   // picked: the user chose a size himself\n"
    "/* The window follows the page: measure what the page needs at the chosen size,\n"
    "   then ask for a window of exactly that. The user stays free to drag it after. */\n"
    "/* Refreshing the page is cheap; asking the window manager to resize is not. Every\n"
    "   notch of the EXP slider used to do both, and the whole editor felt heavy. So the\n"
    "   window is only re-measured when the page really grew or shrank. */\n"
    "let lastH = -1;\n"
    "function maybeZoom(){\n"
    "  const wrap = document.querySelector(\".wrap\");\n"
    "  const h = wrap.scrollHeight;\n"
    "  if (Math.abs(h - lastH) < 2) return;\n"
    "  lastH = h;\n"
    "  applyZoom();\n"
    "}\n"
    "\n"
    "async function applyZoom(){\n"
    "  if (sizing){ again = true; return; }                   /* one pass at a time, but never lose the last */\n"
    "  sizing = true;\n"
    "  try { await sizePass(); }\n"
    "  finally { sizing = false; if (again){ again = false; applyZoom(); } }\n"
    "}\n"
    "\n"
    "async function sizePass(){\n"
    "  const wrap = document.querySelector(\".wrap\");\n"
    "  /* One unit everywhere: the window manager's. 100% is one page pixel per window\n"
    "     unit, which is what the desk itself is measured in, so the page comes out the\n"
    "     same size on every machine. Asking the engine's own pixel ratio is what went\n"
    "     wrong before: KDE tells GTK \"2\" while the desk really runs at 1.25, and the\n"
    "     page came out half size. */\n"
    "  if (winScale === null && window.hostScale){\n"
    "    const r = await hostScale();\n"
    "    winScale = (r && r.scale) || 1;\n"
    "    desk = { w: (r && r.w) || 0, h: (r && r.h) || 0 };\n"
    "    /* How many window units one page pixel takes. It is not the same number on\n"
    "       every desktop - Wayland counts windows in double units and draws double,\n"
    "       which cancels out, while X11 counts real pixels and still draws at the\n"
    "       desktop's text scale - so it is measured rather than assumed: the window's\n"
    "       own inside, as the window manager counts it, against the page's own width. */\n"
    "    if (r && r.cw > 0 && window.innerWidth > 0) unit = r.cw / window.innerWidth;\n"
    "  }\n"
    "  let pick = parseFloat($(\"uiScale\").value) || 1;\n"
    "  /* What the page needs, read from the page as it stands right now - the tab that\n"
    "     is open, the folds that are open, the pictures that have arrived - and undone\n"
    "     of the zoom it is drawn at. Measuring a hidden or half-built page is what let\n"
    "     the window come out one row too short. The width is the design width, fixed,\n"
    "     because measuring inside a narrow window makes the content reflow taller and\n"
    "     the window walks itself into a corner. */\n"
    "  const drawn = parseFloat(wrap.style.zoom) || 1;\n"
    "  const needW = 948;                                     /* .wrap is 920 wide plus its 14px sides */\n"
    "  const needH = Math.ceil(wrap.getBoundingClientRect().height / drawn) + 16;\n"
    "  /* The page opens at 100% and stays there; the only thing that moves it by itself\n"
    "     is a desk too small to hold it, and then only downwards. Anything the user\n"
    "     picks is remembered and wins from then on. */\n"
    "  if (!picked && desk.h && desk.w && pick > 0.5){\n"
    "    const opts = [...$(\"uiScale\").options].map(o => parseFloat(o.value))\n"
    "                                          .filter(v => v <= pick).sort((a, b) => b - a);\n"
    "    const fit = opts.find(v => needH * v * unit <= desk.h && needW * v * unit <= desk.w);\n"
    "    const use = fit !== undefined ? fit : opts[opts.length - 1];\n"
    "    if (use !== pick){ pick = use; $(\"uiScale\").value = String(pick); }\n"
    "  }\n"
    "  wrap.style.zoom = pick;\n"
    "  if (!isFinite(needH) || needH < 100) return;           /* only refuse nonsense */\n"
    "  if (!window.hostResize) return;                        /* in a plain browser: nothing to resize */\n"
    "  let reqW = Math.max(Math.round(needW * pick * unit), 420);\n"
    "  let reqH = Math.max(Math.round(needH * pick * unit), 220);\n"
    "  /* never ask for more window than there is desk: past that the bottom of the\n"
    "     page simply falls off the screen, with no way to reach it. */\n"
    "  if (desk.w) reqW = Math.min(reqW, desk.w);\n"
    "  if (desk.h) reqH = Math.min(reqH, desk.h);\n"
    "  if (reqW === lastW && reqH === lastH2) return;          /* the window is already that size */\n"
    "  lastW = reqW; lastH2 = reqH;\n"
    "  await hostResize(reqW, reqH);\n"
    "}\n"
    "/* Whatever changes the page's height - a card loaded, a tab, a fold, a picture\n"
    "   that arrived - the window has to follow. Watching the page itself is the only\n"
    "   way that cannot be forgotten; guessing which action grew it is how the window\n"
    "   ended up taller than the screen. */\n"
    "if (window.ResizeObserver){\n"
    "  let t = 0;\n"
    "  new ResizeObserver(() => { clearTimeout(t); t = setTimeout(maybeZoom, 60); })\n"
    "    .observe(document.querySelector(\".wrap\"));\n"
    "}\n"
    "$(\"uiScale\").onchange = () => { picked = true; applyZoom();\n"
    "  if (window.hostSavePrefs) hostSavePrefs($(\"uiScale\").value); };   // remembered for next time\n"
    "window.addEventListener(\"load\", applyZoom);\n"
    "setTimeout(applyZoom, 60);\n"
    "function fromB64(b){ const raw = atob(b), u = new Uint8Array(raw.length);\n"
    "  for (let i = 0; i < raw.length; i++) u[i] = raw.charCodeAt(i); return u; }\n"
    "\n"
    "$(\"btnOpen\").onclick = async () => {\n"
    "  const r = await hostOpenCard();\n"
    "  if (!r.ok) return r.err && say(r.err, \"err\");\n"
    "  load(fromB64(r.data), r.name);\n"
    "};\n"
    "document.addEventListener(\"contextmenu\", e => e.preventDefault());   // this is an application, not a web page\n"
    "$(\"btnArt\").onclick = () => openGame();\n"
    "\n"
    "for (const b of $(\"langPick\").querySelectorAll(\"[data-lang]\")) b.onclick = () => {\n"
    "  $(\"langPick\").hidden = true; if (b.dataset.lang) buildArt(b.dataset.lang === \"jp\" ? \"japanese\" : \"world\"); };\n"
    "if (window.hostPrefs) hostPrefs().then(p => {           // the size chosen last time\n"
    "  if (p && p.scale && [...$(\"uiScale\").options].some(o => o.value === p.scale)){\n"
    "    $(\"uiScale\").value = p.scale; picked = true; applyZoom();\n"
    "  }\n"
    "});\n"
    "hostAssets().then(async r => {\n"
    "  if (r && r.lang){ await useArt(r.lang); say(`Artwork loaded - ${r.lang} edition. Open a card to start.`, \"ok\"); }\n"
    "  if (window.hostStartCard){                       /* only when asked for, for testing */\n"
    "    const c = await hostStartCard();\n"
    "    if (c && c.ok){\n"
    "      load(fromB64(c.data), c.name);\n"
    "      if (c.tab){ const b = document.querySelector(`[data-tab=\"${c.tab}\"]`); if (b) b.onclick(); }\n"
    "    }\n"
    "  }\n"
    "});\n"
    "$(\"btnNew\").onclick = () => load(blankCard(), \"new-card.bin\");\n"
    "\n"
    "$(\"btnSave\").onclick = async () => {\n"
    "  wr32(sb(0x14), Math.floor(Date.now() / 1000));                       // the game stamps this at every write\n"
    "  const ref = flagNew && openMasks ? openMasks : { w: rd32(sb(OFF_WEAP)), c: rd32(sb(OFF_COST)), f: rd32(sb(0xB8)) };\n"
    "  wr32(sb(0xD0), ref.w); wr32(sb(0xD4), ref.c); wr32(sb(0xD8), ref.f); // what the card looked like on the way in\n"
    "  seal();\n"
    "  let bin = \"\";\n"
    "  for (let i = 0; i < card.length; i++) bin += String.fromCharCode(card[i]);\n"
    "  const r = await hostSaveCard(fileName, btoa(bin));\n"
    "  if (!r.ok) return r.err && say(r.err, \"err\");\n"
    "  fileName = r.name || fileName;\n"
    "  say(`${fileName} saved - ready to use.`, \"ok\");\n"
    "};\n"
    "\n"
    "const drop = $(\"drop\");\n"
    "drop.onclick = () => $(\"btnOpen\").onclick();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    "\n"
;
